  '/aistatus': '/ai_status',
  '/lasterror': '/last_error',
  '/aion': '/ai_on',
  '/aioff': '/ai_off',
  '/foobarunknown': '/foobar_unknown',
};

const command = ALIASES[rawCmd] || rawCmd;
const args = parts.slice(1);

return [{ json: {
  command,
  command_raw: rawCmd,
  args,
  text,
  user_id: String(from.id || root.user_id || j.user_id || ''),
  username: from.username || '',
  chat_id: String(chat.id || root.chat_id || j.chat_id || ''),
  raw_ok: Boolean(text),
}}];

const lead = $('Normalize Command').first().json;
const rows = $('Read Authorization Config').all().map((i) => i.json);
const map = {};
for (const r of rows) {
  if (r.key != null) map[String(r.key)] = String(r.value ?? '');
}
const allow = String(map.admin_user_ids || '')
  .split(/[,;\s]+/)
  .map((s) => s.trim())
  .filter(Boolean);
const authorized = allow.length === 0 ? false : allow.includes(String(lead.user_id));

// Read CONFIG emits one item per row; emit authorization decision only once.
const thisKey = String(($input.first().json && $input.first().json.key) || '');
const firstKey = rows[0] ? String(rows[0].key) : '';
if (rows.length > 1 && thisKey && firstKey && thisKey !== firstKey) {
  return [];
}

return [{
  json: {
    ...lead,
    config_map: map,
    authorized,
    environment: map.environment || 'dev',
    ai_enabled: map.ai_enabled === 'true',
  },
}];

const j = $input.first().json;
const m = j.config_map || {};

function formatMoscow(v) {
  const s = String(v || '').trim();
  if (!s) return '—';
  const d = new Date(s);
  if (Number.isNaN(d.getTime())) return '—';
  const parts = new Intl.DateTimeFormat('ru-RU', {
    timeZone: 'Europe/Moscow',
    day: '2-digit',
    month: '2-digit',
    year: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
    hour12: false,
  }).formatToParts(d);
  const get = (t) => parts.find((p) => p.type === t)?.value || '';
  return `${get('day')}.${get('month')}.${get('year')} ${get('hour')}:${get('minute')} МСК`;
}

