function parseTs(r) {
  const candidates = [r.processed_at, r.clean_written_at, r.updated_at, r.created_at, r.ts, r.timestamp];
  for (const c of candidates) {
    if (!c) continue;
    const d = new Date(c);
    if (!Number.isNaN(d.getTime())) return d.getTime();
  }
  return null;
}

function isSynthetic(r) {
  const blob = JSON.stringify(r).toLowerCase();
  return blob.includes('synthetic_test')
    || blob.includes('phase_3b')
    || String(r.fixture_id || '').startsWith('TG')
    || String(r.source_marker || '').toUpperCase() === 'SYNTHETIC_TEST';
}

const filtered = rows.filter((r) => {
  const syn = isSynthetic(r);
  if (isProd) {
    if (syn) return false;
  } else {
    if (!syn) return false;
  }
  const ts = parseTs(r);
  if (ts == null) return !isProd; // undated synthetic ok in dev only
  return (now - ts) <= windowMs;
});

const counts = {
  total: filtered.length,
  neu: 0,
  repeat: 0,
  possible: 0,
  reprocessed: 0,
  ai_off: 0,
  ai_on: 0,
