  ok: 0,
  needs: 0,
  bad: 0,
  errors: 0,
};

for (const r of filtered) {
  const dup = String(r.duplicate_status || r.duplicate_match_type || r.dup || '').toLowerCase();
  if (dup === 'new') counts.neu++;
  else if (dup === 'repeat') counts.repeat++;
  else if (dup === 'possible' || dup === 'possible_repeat') counts.possible++;
  else if (dup === 'reprocessed') counts.reprocessed++;

  const mode = String(r.processing_mode || r.ai_mode || '').toLowerCase();
  if (mode === 'ai_on' || mode === 'ai') counts.ai_on++;
  else if (mode === 'ai_fallback' || mode === 'fallback') counts.ai_fallback++;
  else counts.ai_off++;

  const q = String(r.quality_status || r.quality || '').toLowerCase();
  if (q === 'ok') counts.ok++;
  else if (q === 'needs_data' || q === 'poor') counts.needs++;
